        "content": "import { describe, expect, test } from \"bun:test\";\nimport { validateJson } from \"./validate-json\";\n\ndescribe(\"validateJson\", () => {\n  test(\"accepts a valid JSON object\", () => {\n    const result = validateJson('{\"key\": \"value\"}');\n    expect(result.valid).toBe(true);\n    expect(result).toEqual({ valid: true, data: { key: \"value\" } });\n  });\n\n  test(\"accepts a valid JSON array\", () => {\n    const result = validateJson(\"[1, 2, 3]\");\n    expect(result.valid).toBe(true);\n    expect(result).toEqual({ valid: true, data: [1, 2, 3] });\n  });\n\n  test(\"accepts a JSON primitive string\", () => {\n    const result = validateJson('\"hello\"');\n    expect(result.valid).toBe(true);\n    expect(result).toEqual({ valid: true, data: \"hello\" });\n  });\n\n  test(\"accepts a JSON number\", () => {\n    const result = validateJson(\"42\");\n    expect(result.valid).toBe(true);\n    expect(result).toEqual({ valid: true, data: 42 });\n  });\n\n  test(\"accepts JSON with whitespace padding\", () => {\n    const result = validateJson('  { \"a\": 1 }  ');\n    expect(result.valid).toBe(true);\n    expect(result).toEqual({ valid: true, data: { a: 1 } });\n  });\n\n  test(\"rejects empty input\", () => {\n    const result = validateJson(\"\");\n    expect(result.valid).toBe(false);\n    if (!result.valid) {\n      expect(result.error).toBe(\"Empty input\");\n    }\n  });\n\n  test(\"rejects whitespace-only input\", () => {\n    const result = validateJson(\"   \");\n    expect(result.valid).toBe(false);\n    if (!result.valid) {\n      expect(result.error).toBe(\"Empty input\");\n    }\n  });\n\n  test(\"rejects invalid JSON with trailing comma\", () => {\n    const result = validateJson('{\"a\": 1,}');\n    expect(result.valid).toBe(false);\n  });\n\n  test(\"rejects single-quoted strings\", () => {\n    const result = validateJson(\"{'key': 'value'}\");\n    expect(result.valid).toBe(false);\n  });\n\n  test(\"rejects plain text\", () => {\n    const result = validateJson(\"not json at all\");\n    expect(result.valid).toBe(false);\n  });\n\n  test(\"returns a descriptive error message for invalid JSON\", () => {\n    const result = validateJson(\"{bad}\");\n    expect(result.valid).toBe(false);\n    if (!result.valid) {\n      expect(result.error).toBeTruthy();\n      expect(result.error).not.toBe(\"Empty input\");\n    }\n  });\n});\n"
