import { describe, expect, test } from "bun:test";
import { greet, greetFormal, greetWithMessage, add } from "./utils";

describe("utils", () => {
  test("greet returns greeting message", () => {
    expect(greet("Alice")).toBe("Hello, Alice!");
  });

  test("add returns sum of two numbers", () => {
    expect(add(2, 3)).toBe(5);
  });
});

describe("greetFormal", () => {
  test("returns formal greeting with name", () => {
    expect(greetFormal("Alice")).toBe("Good day, Alice. Welcome!");
  });

  test("handles empty string name", () => {
    expect(greetFormal("")).toBe("Good day, . Welcome!");
  });

  test("handles name with spaces", () => {
    expect(greetFormal("Dr. Smith")).toBe("Good day, Dr. Smith. Welcome!");
  });
});

describe("greetWithMessage", () => {
  test("returns greeting with custom message", () => {
    expect(greetWithMessage("Alice", "How are you?")).toBe(
      "Hello, Alice! How are you?",
    );
  });

  test("handles empty string name", () => {
    expect(greetWithMessage("", "Welcome aboard")).toBe(
      "Hello, ! Welcome aboard",
    );
  });

  test("handles empty string message", () => {
    expect(greetWithMessage("Alice", "")).toBe("Hello, Alice! ");
  });

  test("handles both empty strings", () => {
    expect(greetWithMessage("", "")).toBe("Hello, ! ");
  });
});

