      items.push(`{"id":${i},"name":"test user ${i}"}`);
    }
    const payload = `[${items.join(",")}]`;

    const result = validate(payload, schema);
    expect(result.valid).toBe(true);
    expect(result.durationMs).toBeLessThan(200);
  });
});

/**
 * TypeScript type definitions for the JSON validation system.
 */

/** Supported JSON value types for schema validation. */
export type JsonType = "string" | "number" | "boolean" | "object" | "array" | "null";

/** Schema definition for validating JSON structures. */
export interface JsonSchema {
  /** Expected type of the value. */
  type?: JsonType;
  /** For objects: map of property names to their sub-schemas. */
  properties?: Record<string, JsonSchema>;
  /** For objects: list of property names that must be present. */
  required?: string[];
  /** For arrays: schema that each array item must satisfy. */
  items?: JsonSchema;
  /** For arrays: minimum number of items. */
  minItems?: number;
  /** For arrays: maximum number of items. */
  maxItems?: number;
  /** For strings: minimum length. */
  minLength?: number;
  /** For strings: maximum length. */
  maxLength?: number;
  /** For numbers: minimum value (inclusive). */
  minimum?: number;
  /** For numbers: maximum value (inclusive). */
  maximum?: number;
}

/** A single validation error with location and message. */
export interface ValidationError {
  /** JSON pointer path to the invalid value (e.g. "/users/0/name"). */
  path: string;
  /** Human-readable error message. */
  message: string;
  /** The schema constraint that was violated. */
  rule: string;
}

/** Result of a validation operation. */
export interface ValidationResult {
  /** Whether the input passed all checks. */
  valid: boolean;
  /** List of errors found (empty when valid). */
  errors: ValidationError[];
  /** Time taken for validation in milliseconds. */
  durationMs: number;
}

/** Compiled validator function produced by the schema compiler. */
export type CompiledValidator = (value: unknown, path: string, errors: ValidationError[]) => void;

/**
 * Ultra-performant JSON validation script.
 *
 * Uses a single-pass character scanner for structural validation and a
 * compiled-validator pattern for schema checks.
 */

import type {
  JsonSchema,
  JsonType,
  ValidationResult,
  ValidationError,
  CompiledValidator,
} from "./types/schema";

// Re-export types for consumer convenience
export type { JsonSchema, ValidationResult, ValidationError };

// ---------------------------------------------------------------------------
// Character codes (avoids repeated charCodeAt string allocations)
// ---------------------------------------------------------------------------
const CH_SPACE = 0x20;
const CH_TAB = 0x09;
const CH_NL = 0x0a;
const CH_CR = 0x0d;
const CH_QUOTE = 0x22;
const CH_COMMA = 0x2c;
const CH_COLON = 0x3a;
const CH_LBRACE = 0x7b;
const CH_RBRACE = 0x7d;
const CH_LBRACKET = 0x5b;
const CH_RBRACKET = 0x5d;
const CH_BACKSLASH = 0x5c;
const CH_SLASH = 0x2f;
const CH_MINUS = 0x2d;
const CH_PLUS = 0x2b;
const CH_DOT = 0x2e;
const CH_0 = 0x30;
const CH_9 = 0x39;
const CH_a = 0x61;
const CH_e = 0x65;
const CH_E = 0x45;
const CH_f = 0x66;
const CH_n = 0x6e;
const CH_t = 0x74;

// ---------------------------------------------------------------------------
// Single-pass structural JSON validator (no deserialization)
// ---------------------------------------------------------------------------

/**
 * Validate JSON syntax using a single-pass character scanner.
 * Returns an error message string on failure, or null on success.
 */
export function validateStructure(input: string): string | null {
  const len = input.length;
  let pos = 0;

  function skipWhitespace(): void {
    while (pos < len) {
      const c = input.charCodeAt(pos);
      if (c === CH_SPACE || c === CH_TAB || c === CH_NL || c === CH_CR) {
        pos++;
      } else {
        break;
      }
    }
  }

  function parseString(): string | null {
    if (pos >= len || input.charCodeAt(pos) !== CH_QUOTE) {
      return `Expected '"' at position ${pos}`;
    }
    pos++; // skip opening quote
    while (pos < len) {
      const c = input.charCodeAt(pos);
      if (c === CH_BACKSLASH) {
        pos++; // skip backslash
        if (pos >= len) return `Unexpected end of input in string escape at position ${pos}`;
        const esc = input.charCodeAt(pos);
        // Valid escape characters: " \ / b f n r t u
        if (
          esc === CH_QUOTE ||
          esc === CH_BACKSLASH ||
          esc === CH_SLASH ||
          esc === 0x62 || // b
          esc === CH_f ||
          esc === CH_n ||
          esc === 0x72 || // r
          esc === CH_t ||
          esc === 0x75   // u
        ) {
          if (esc === 0x75) {
            // Unicode escape: expect 4 hex digits
            for (let i = 0; i < 4; i++) {
              pos++;
              if (pos >= len) return `Unexpected end of input in unicode escape at position ${pos}`;
              const h = input.charCodeAt(pos);
              if (
                !(h >= CH_0 && h <= CH_9) &&
                !(h >= 0x41 && h <= 0x46) &&
                !(h >= CH_a && h <= CH_f)
              ) {
                return `Invalid unicode escape character at position ${pos}`;
              }
            }
          }
          pos++;
        } else {
          return `Invalid escape character '\\${input[pos]}' at position ${pos}`;
        }
      } else if (c === CH_QUOTE) {
        pos++; // skip closing quote
        return null;
      } else if (c < 0x20) {
        return `Invalid control character in string at position ${pos}`;
      } else {
        pos++;
      }
    }
    return `Unterminated string starting at position ${pos}`;
  }

  function parseNumber(): string | null {
    const start = pos;
    // Optional minus
    if (pos < len && input.charCodeAt(pos) === CH_MINUS) pos++;

    // Integer part
    if (pos >= len) return `Unexpected end of input in number at position ${pos}`;
    if (input.charCodeAt(pos) === CH_0) {
      pos++;
      // After leading zero, must not be followed by digit
      if (pos < len && input.charCodeAt(pos) >= CH_0 && input.charCodeAt(pos) <= CH_9) {
        return `Leading zeros not allowed in number at position ${start}`;
      }
    } else if (input.charCodeAt(pos) >= CH_0 + 1 && input.charCodeAt(pos) <= CH_9) {
      while (pos < len && input.charCodeAt(pos) >= CH_0 && input.charCodeAt(pos) <= CH_9) pos++;
    } else {
      return `Invalid number at position ${start}`;
    }

    // Fraction
    if (pos < len && input.charCodeAt(pos) === CH_DOT) {
      pos++;
      if (pos >= len || input.charCodeAt(pos) < CH_0 || input.charCodeAt(pos) > CH_9) {
        return `Expected digit after decimal point at position ${pos}`;
      }
      while (pos < len && input.charCodeAt(pos) >= CH_0 && input.charCodeAt(pos) <= CH_9) pos++;
    }

    // Exponent
    if (pos < len && (input.charCodeAt(pos) === CH_e || input.charCodeAt(pos) === CH_E)) {
      pos++;
      if (pos < len && (input.charCodeAt(pos) === CH_PLUS || input.charCodeAt(pos) === CH_MINUS)) pos++;
      if (pos >= len || input.charCodeAt(pos) < CH_0 || input.charCodeAt(pos) > CH_9) {
        return `Expected digit in exponent at position ${pos}`;
      }
      while (pos < len && input.charCodeAt(pos) >= CH_0 && input.charCodeAt(pos) <= CH_9) pos++;
    }

    return null;
  }

  function parseValue(): string | null {
    skipWhitespace();
    if (pos >= len) return `Unexpected end of input at position ${pos}`;

    const c = input.charCodeAt(pos);

    // String
    if (c === CH_QUOTE) return parseString();

    // Object
    if (c === CH_LBRACE) {
      pos++;
      skipWhitespace();
      if (pos < len && input.charCodeAt(pos) === CH_RBRACE) {
        pos++;
        return null;
      }
      while (true) {
        skipWhitespace();
        // Key must be a string
        if (pos >= len || input.charCodeAt(pos) !== CH_QUOTE) {
          return `Expected property name (string) at position ${pos}`;
        }
        const keyErr = parseString();
        if (keyErr) return keyErr;

        skipWhitespace();
        if (pos >= len || input.charCodeAt(pos) !== CH_COLON) {
          return `Expected ':' after property name at position ${pos}`;
        }
        pos++;

        const valErr = parseValue();
        if (valErr) return valErr;

        skipWhitespace();
        if (pos >= len) return `Unexpected end of input in object at position ${pos}`;
        if (input.charCodeAt(pos) === CH_RBRACE) {
          pos++;
          return null;
        }
        if (input.charCodeAt(pos) !== CH_COMMA) {
          return `Expected ',' or '}' in object at position ${pos}`;
        }
        pos++;
      }
    }

    // Array
    if (c === CH_LBRACKET) {
      pos++;
      skipWhitespace();
      if (pos < len && input.charCodeAt(pos) === CH_RBRACKET) {
        pos++;
        return null;
      }
      while (true) {
        const valErr = parseValue();
        if (valErr) return valErr;

        skipWhitespace();
        if (pos >= len) return `Unexpected end of input in array at position ${pos}`;
        if (input.charCodeAt(pos) === CH_RBRACKET) {
          pos++;
          return null;
        }
        if (input.charCodeAt(pos) !== CH_COMMA) {
          return `Expected ',' or ']' in array at position ${pos}`;
        }
        pos++;
      }
    }

    // Number
    if (c === CH_MINUS || (c >= CH_0 && c <= CH_9)) return parseNumber();

    // true
    if (c === CH_t) {
      if (input.slice(pos, pos + 4) === "true") {
        pos += 4;
        return null;
      }
      return `Invalid token at position ${pos}`;
    }

    // false
    if (c === CH_f) {
      if (input.slice(pos, pos + 5) === "false") {
        pos += 5;
        return null;
      }
      return `Invalid token at position ${pos}`;
    }

    // null
    if (c === CH_n) {
      if (input.slice(pos, pos + 4) === "null") {
        pos += 4;
        return null;
      }
      return `Invalid token at position ${pos}`;
    }

    return `Unexpected character '${input[pos]}' at position ${pos}`;
  }

  const err = parseValue();
  if (err) return err;

  skipWhitespace();
  if (pos < len) {
    return `Unexpected content after JSON value at position ${pos}`;
  }

  return null;
}

// ---------------------------------------------------------------------------
// Schema compiler
// ---------------------------------------------------------------------------

function jsonTypeOf(value: unknown): JsonType {
  if (value === null) return "null";
  if (Array.isArray(value)) return "array";
  return typeof value as JsonType;
}

/**
 * Compile a JsonSchema into a fast validator function.
 * The compiled function mutates the provided errors array for zero-allocation
 * error collection.
 */
export function compileSchema(schema: JsonSchema): CompiledValidator {
  const checks: CompiledValidator[] = [];

  if (schema.type !== undefined) {
    const expectedType = schema.type;
    checks.push((value, path, errors) => {
      if (jsonTypeOf(value) !== expectedType) {
        errors.push({
          path,
          message: `Expected type "${expectedType}" but got "${jsonTypeOf(value)}"`,
          rule: "type",
        });
      }
    });
  }

  if (schema.required !== undefined) {
    const requiredFields = schema.required;
    checks.push((value, path, errors) => {
      if (jsonTypeOf(value) !== "object") return;
      const obj = value as Record<string, unknown>;
      for (let i = 0; i < requiredFields.length; i++) {
        const field = requiredFields[i];
        if (!(field in obj)) {
          errors.push({
            path: path === "" ? `/${field}` : `${path}/${field}`,
            message: `Missing required field "${field}"`,
            rule: "required",
          });
        }
      }
    });
  }

  if (schema.properties !== undefined) {
    const propEntries = Object.entries(schema.properties);
    const compiledProps: Array<[string, CompiledValidator]> = propEntries.map(
      ([key, subSchema]) => [key, compileSchema(subSchema)]
    );
    checks.push((value, path, errors) => {
      if (jsonTypeOf(value) !== "object") return;
      const obj = value as Record<string, unknown>;
      for (let i = 0; i < compiledProps.length; i++) {
        const [key, validator] = compiledProps[i];
        if (key in obj) {
          validator(obj[key], path === "" ? `/${key}` : `${path}/${key}`, errors);
        }
      }
    });
  }

  if (schema.items !== undefined) {
    const itemValidator = compileSchema(schema.items);
    checks.push((value, path, errors) => {
      if (!Array.isArray(value)) return;
      for (let i = 0; i < value.length; i++) {
        itemValidator(value[i], `${path}/${i}`, errors);
      }
    });
  }

  if (schema.minItems !== undefined) {
    const min = schema.minItems;
    checks.push((value, path, errors) => {
      if (Array.isArray(value) && value.length < min) {
        errors.push({
          path,
          message: `Array must have at least ${min} items but has ${value.length}`,
          rule: "minItems",
        });
      }
    });
  }

  if (schema.maxItems !== undefined) {
    const max = schema.maxItems;
    checks.push((value, path, errors) => {
      if (Array.isArray(value) && value.length > max) {
        errors.push({
          path,
          message: `Array must have at most ${max} items but has ${value.length}`,
          rule: "maxItems",
        });
      }
    });
  }

  if (schema.minLength !== undefined) {
    const min = schema.minLength;
    checks.push((value, path, errors) => {
      if (typeof value === "string" && value.length < min) {
        errors.push({
          path,
          message: `String must be at least ${min} characters but has ${value.length}`,
          rule: "minLength",
        });
      }
    });
  }

  if (schema.maxLength !== undefined) {
    const max = schema.maxLength;
    checks.push((value, path, errors) => {
      if (typeof value === "string" && value.length > max) {
        errors.push({
          path,
          message: `String must be at most ${max} characters but has ${value.length}`,
          rule: "maxLength",
        });
      }
    });
  }

  if (schema.minimum !== undefined) {
    const min = schema.minimum;
    checks.push((value, path, errors) => {
      if (typeof value === "number" && value < min) {
        errors.push({
          path,
          message: `Number must be >= ${min} but is ${value}`,
          rule: "minimum",
        });
      }
    });
  }

  if (schema.maximum !== undefined) {
    const max = schema.maximum;
    checks.push((value, path, errors) => {
      if (typeof value === "number" && value > max) {
        errors.push({
          path,
          message: `Number must be <= ${max} but is ${value}`,
          rule: "maximum",
        });
      }
    });
  }

  // Combine all checks into a single function for minimal call overhead
  const checkCount = checks.length;
  if (checkCount === 0) {
    return () => {};
  }
  if (checkCount === 1) {
    return checks[0];
  }
  return (value, path, errors) => {
    for (let i = 0; i < checkCount; i++) {
      checks[i](value, path, errors);
    }
  };
}

// ---------------------------------------------------------------------------
// Public API
// ---------------------------------------------------------------------------

/**
 * Validate a JSON string, optionally against a schema.
 *
 * Without a schema, performs ultra-fast structural validation using a
 * single-pass character scanner (no deserialization).
 *
 * With a schema, parses the JSON and runs pre-compiled schema checks.
 */
export function validate(input: string, schema?: JsonSchema): ValidationResult {
  const start = performance.now();

  // Phase 1: structural validation (always runs)
  const structErr = validateStructure(input);
  if (structErr) {
    return {
      valid: false,
      errors: [{ path: "", message: structErr, rule: "syntax" }],
      durationMs: performance.now() - start,
    };
  }

  // If no schema, structural validity is sufficient
  if (!schema) {
    return {
      valid: true,
      errors: [],
      durationMs: performance.now() - start,
    };
  }

  // Phase 2: schema validation (requires parsing)
  const parsed: unknown = JSON.parse(input);
  const compiled = compileSchema(schema);
  const errors: ValidationError[] = [];
  compiled(parsed, "", errors);

  return {
    valid: errors.length === 0,
    errors,
    durationMs: performance.now() - start,
  };
}

// ---------------------------------------------------------------------------
// CLI entrypoint
// ---------------------------------------------------------------------------

async function readStdin(): Promise<string> {
  const chunks: Uint8Array[] = [];
  const reader = Bun.stdin.stream().getReader();
  while (true) {
    const { done, value } = await reader.read();
    if (done) break;
    if (value) chunks.push(value);
  }
  return Buffer.concat(chunks).toString("utf-8");
}

async function main(): Promise<void> {
  const args = process.argv.slice(2);
  let schemaPath: string | undefined;
  let inputPath: string | undefined;

  // Parse arguments: [input-file] [--schema schema-file]
  for (let i = 0; i < args.length; i++) {
    if (args[i] === "--schema" && i + 1 < args.length) {
      schemaPath = args[++i];
    } else if (!inputPath) {
      inputPath = args[i];
    }
  }

  let input: string;
  if (inputPath) {
    const file = Bun.file(inputPath);
    if (!(await file.exists())) {
      console.error(JSON.stringify({ error: `File not found: ${inputPath}` }));
      process.exit(2);
    }
    input = await file.text();
  } else {
    input = await readStdin();
  }

  let schema: JsonSchema | undefined;
  if (schemaPath) {
    const schemaFile = Bun.file(schemaPath);
    if (!(await schemaFile.exists())) {
      console.error(JSON.stringify({ error: `Schema file not found: ${schemaPath}` }));
      process.exit(2);
    }
    schema = JSON.parse(await schemaFile.text()) as JsonSchema;
  }

  const result = validate(input, schema);
  console.log(JSON.stringify(result, null, 2));
  process.exit(result.valid ? 0 : 1);
}

// Run CLI when executed directly
const isMainModule =
  typeof Bun !== "undefined" && Bun.main === import.meta.path;

if (isMainModule) {
  main();
}

import { describe, expect, test } from "bun:test";
import { validate, validateStructure, compileSchema } from "./validate-json";
import type { JsonSchema, ValidationError } from "./types/schema";

// ---------------------------------------------------------------------------
// Structural validation (no schema)
// ---------------------------------------------------------------------------

describe("validateStructure", () => {
  test("accepts a simple object", () => {
    expect(validateStructure('{"a": 1}')).toBeNull();
  });

  test("accepts a simple array", () => {
    expect(validateStructure("[1, 2, 3]")).toBeNull();
  });

  test("accepts a bare string", () => {
    expect(validateStructure('"hello"')).toBeNull();
  });

  test("accepts a bare number", () => {
    expect(validateStructure("42")).toBeNull();
  });

  test("accepts true, false, null", () => {
    expect(validateStructure("true")).toBeNull();
    expect(validateStructure("false")).toBeNull();
    expect(validateStructure("null")).toBeNull();
  });

  test("accepts an empty object", () => {
    expect(validateStructure("{}")).toBeNull();
  });

  test("accepts an empty array", () => {
    expect(validateStructure("[]")).toBeNull();
  });

  test("accepts negative numbers", () => {
    expect(validateStructure("-123")).toBeNull();
    expect(validateStructure("-0.5")).toBeNull();
  });

  test("accepts numbers with exponents", () => {
    expect(validateStructure("1e10")).toBeNull();
    expect(validateStructure("1.5E-3")).toBeNull();
    expect(validateStructure("2.0e+4")).toBeNull();
  });

  test("accepts strings with escape sequences", () => {
    expect(validateStructure('"hello\\nworld"')).toBeNull();
    expect(validateStructure('"tab\\there"')).toBeNull();
    expect(validateStructure('"unicode\\u00E9"')).toBeNull();
    expect(validateStructure('"quote\\"here"')).toBeNull();
  });

  test("accepts deeply nested structures", () => {
    const deep = '{"a":{"b":{"c":{"d":{"e":[1,2,{"f":true}]}}}}}';
    expect(validateStructure(deep)).toBeNull();
  });

  test("accepts whitespace around values", () => {
    expect(validateStructure('  { "a" : 1 }  ')).toBeNull();
    expect(validateStructure("\n[\n1\n,\n2\n]\n")).toBeNull();
  });

  test("rejects trailing commas in objects", () => {
    const err = validateStructure('{"a": 1,}');
    expect(err).not.toBeNull();
    expect(err).toContain("Expected property name");
  });

  test("rejects trailing commas in arrays", () => {
    const err = validateStructure("[1, 2,]");
    expect(err).not.toBeNull();
  });

  test("rejects unquoted keys", () => {
    const err = validateStructure("{a: 1}");
    expect(err).not.toBeNull();
    expect(err).toContain("Expected property name");
  });

  test("rejects truncated input (unclosed object)", () => {
    const err = validateStructure('{"a": 1');
    expect(err).not.toBeNull();
  });

  test("rejects truncated input (unclosed array)", () => {
    const err = validateStructure("[1, 2");
    expect(err).not.toBeNull();
  });

  test("rejects truncated input (unterminated string)", () => {
    const err = validateStructure('"hello');
    expect(err).not.toBeNull();
  });

  test("rejects leading zeros in numbers", () => {
    const err = validateStructure("012");
    expect(err).not.toBeNull();
    expect(err).toContain("Leading zeros");
  });

  test("rejects extra content after valid JSON", () => {
    const err = validateStructure("{}[]");
    expect(err).not.toBeNull();
    expect(err).toContain("Unexpected content");
  });

  test("rejects empty input", () => {
    const err = validateStructure("");
    expect(err).not.toBeNull();
  });

  test("rejects invalid escape sequences", () => {
    const err = validateStructure('"\\x41"');
    expect(err).not.toBeNull();
    expect(err).toContain("Invalid escape");
  });

  test("rejects single quotes", () => {
    const err = validateStructure("'hello'");
    expect(err).not.toBeNull();
  });
});

// ---------------------------------------------------------------------------
// validate() without schema
// ---------------------------------------------------------------------------

describe("validate without schema", () => {
  test("returns valid for correct JSON", () => {
    const result = validate('{"name": "test"}');
    expect(result.valid).toBe(true);
    expect(result.errors).toHaveLength(0);
    expect(result.durationMs).toBeGreaterThanOrEqual(0);
  });

  test("returns invalid for malformed JSON", () => {
    const result = validate("{bad json}");
    expect(result.valid).toBe(false);
    expect(result.errors).toHaveLength(1);
    expect(result.errors[0].rule).toBe("syntax");
  });
});

// ---------------------------------------------------------------------------
// Schema validation
// ---------------------------------------------------------------------------

describe("validate with schema", () => {
  test("validates type constraint", () => {
    const schema: JsonSchema = { type: "object" };
    expect(validate('{"a": 1}', schema).valid).toBe(true);
    const bad = validate("42", schema);
    expect(bad.valid).toBe(false);
    expect(bad.errors[0].rule).toBe("type");
  });

  test("validates required fields", () => {
    const schema: JsonSchema = {
      type: "object",
      required: ["name", "age"],
    };

    expect(validate('{"name": "Alice", "age": 30}', schema).valid).toBe(true);

    const missing = validate('{"name": "Alice"}', schema);
    expect(missing.valid).toBe(false);
    expect(missing.errors).toHaveLength(1);
    expect(missing.errors[0].rule).toBe("required");
    expect(missing.errors[0].path).toBe("/age");
  });

  test("validates nested object properties", () => {
    const schema: JsonSchema = {
      type: "object",
      properties: {
        user: {
          type: "object",
          required: ["name"],
          properties: {
            name: { type: "string" },
            age: { type: "number" },
          },
        },
      },
    };

    expect(validate('{"user": {"name": "Alice", "age": 30}}', schema).valid).toBe(true);

    const wrongType = validate('{"user": {"name": 123}}', schema);
    expect(wrongType.valid).toBe(false);
    expect(wrongType.errors[0].path).toBe("/user/name");
    expect(wrongType.errors[0].rule).toBe("type");
  });

  test("validates array items", () => {
    const schema: JsonSchema = {
      type: "array",
      items: { type: "number" },
    };

    expect(validate("[1, 2, 3]", schema).valid).toBe(true);

    const bad = validate('[1, "two", 3]', schema);
    expect(bad.valid).toBe(false);
    expect(bad.errors[0].path).toBe("/1");
  });

  test("validates minItems and maxItems", () => {
    const schema: JsonSchema = {
      type: "array",
      minItems: 2,
      maxItems: 4,
    };

    expect(validate("[1, 2, 3]", schema).valid).toBe(true);

    const tooFew = validate("[1]", schema);
    expect(tooFew.valid).toBe(false);
    expect(tooFew.errors[0].rule).toBe("minItems");

    const tooMany = validate("[1, 2, 3, 4, 5]", schema);
    expect(tooMany.valid).toBe(false);
    expect(tooMany.errors[0].rule).toBe("maxItems");
  });

  test("validates string minLength and maxLength", () => {
    const schema: JsonSchema = {
      type: "string",
      minLength: 3,
      maxLength: 10,
    };

    expect(validate('"hello"', schema).valid).toBe(true);

    const tooShort = validate('"hi"', schema);
    expect(tooShort.valid).toBe(false);
    expect(tooShort.errors[0].rule).toBe("minLength");

    const tooLong = validate('"this string is too long"', schema);
    expect(tooLong.valid).toBe(false);
    expect(tooLong.errors[0].rule).toBe("maxLength");
  });

  test("validates number minimum and maximum", () => {
    const schema: JsonSchema = {
      type: "number",
      minimum: 0,
      maximum: 100,
    };

    expect(validate("50", schema).valid).toBe(true);

    const tooLow = validate("-1", schema);
    expect(tooLow.valid).toBe(false);
    expect(tooLow.errors[0].rule).toBe("minimum");

    const tooHigh = validate("101", schema);
    expect(tooHigh.valid).toBe(false);
    expect(tooHigh.errors[0].rule).toBe("maximum");
  });

  test("structural errors take priority over schema errors", () => {
    const schema: JsonSchema = { type: "object" };
    const result = validate("{bad}", schema);
    expect(result.valid).toBe(false);
    expect(result.errors[0].rule).toBe("syntax");
  });

  test("reports multiple schema errors", () => {
    const schema: JsonSchema = {
      type: "object",
      required: ["a", "b", "c"],
    };
    const result = validate("{}", schema);
    expect(result.valid).toBe(false);
    expect(result.errors).toHaveLength(3);
  });
});

// ---------------------------------------------------------------------------
// compileSchema direct tests
// ---------------------------------------------------------------------------

describe("compileSchema", () => {
  test("empty schema accepts anything", () => {
    const validator = compileSchema({});
    const errors: ValidationError[] = [];
    validator("anything", "", errors);
    expect(errors).toHaveLength(0);
  });

  test("compiled validator is reusable", () => {
    const validator = compileSchema({ type: "number" });
    const e1: ValidationError[] = [];
    validator(42, "", e1);
    expect(e1).toHaveLength(0);

    const e2: ValidationError[] = [];
    validator("not a number", "", e2);
    expect(e2).toHaveLength(1);
  });
});

// ---------------------------------------------------------------------------
// Edge cases
// ---------------------------------------------------------------------------

describe("edge cases", () => {
  test("validates empty object", () => {
    const result = validate("{}");
    expect(result.valid).toBe(true);
  });

  test("validates empty array", () => {
    const result = validate("[]");
    expect(result.valid).toBe(true);
  });

  test("validates null literal", () => {
    const result = validate("null", { type: "null" });
    expect(result.valid).toBe(true);
  });

  test("validates boolean literal", () => {
    expect(validate("true", { type: "boolean" }).valid).toBe(true);
    expect(validate("false", { type: "boolean" }).valid).toBe(true);
  });

  test("handles deeply nested schema validation", () => {
    const schema: JsonSchema = {
      type: "object",
      properties: {
        level1: {
          type: "object",
          properties: {
            level2: {
              type: "object",
              properties: {
                level3: {
                  type: "object",
                  properties: {
                    value: { type: "number" },
                  },
                },
              },
            },
          },
        },
      },
    };

    const json = '{"level1":{"level2":{"level3":{"value":42}}}}';
    expect(validate(json, schema).valid).toBe(true);

    const bad = '{"level1":{"level2":{"level3":{"value":"string"}}}}';
    const result = validate(bad, schema);
    expect(result.valid).toBe(false);
    expect(result.errors[0].path).toBe("/level1/level2/level3/value");
  });

  test("handles arrays of objects with schemas", () => {
    const schema: JsonSchema = {
      type: "array",
      items: {
        type: "object",
        required: ["id"],
        properties: {
          id: { type: "number" },
          name: { type: "string" },
        },
      },
    };

    const valid = '[{"id": 1, "name": "a"}, {"id": 2, "name": "b"}]';
    expect(validate(valid, schema).valid).toBe(true);

    const invalid = '[{"id": 1}, {"name": "missing id"}]';
    const result = validate(invalid, schema);
    expect(result.valid).toBe(false);
    expect(result.errors[0].path).toBe("/1/id");
  });
});

// ---------------------------------------------------------------------------
// Performance benchmark
// ---------------------------------------------------------------------------

describe("performance", () => {
  test("validates 1MB payload under 50ms", () => {
    // Generate a ~1MB JSON payload
    const items: string[] = [];
    const singleItem = '{"id":1,"name":"test user","email":"user@example.com","active":true}';
    const bytesPerItem = singleItem.length + 1; // +1 for comma
    const targetBytes = 1_000_000;
    const count = Math.ceil(targetBytes / bytesPerItem);

    for (let i = 0; i < count; i++) {
      items.push(`{"id":${i},"name":"test user ${i}","email":"user${i}@example.com","active":true}`);
    }
    const payload = `[${items.join(",")}]`;
    expect(payload.length).toBeGreaterThan(1_000_000);

    // Structural validation benchmark
    const start = performance.now();
    const structErr = validateStructure(payload);
    const elapsed = performance.now() - start;

    expect(structErr).toBeNull();
    expect(elapsed).toBeLessThan(50);
  });

  test("schema validation of 1MB payload completes under 200ms", () => {
    const schema: JsonSchema = {
      type: "array",
      items: {
        type: "object",
        required: ["id", "name"],
        properties: {
          id: { type: "number", minimum: 0 },
          name: { type: "string", minLength: 1 },
        },
      },
    };

    const items: string[] = [];
    const targetBytes = 1_000_000;
    const singleItem = '{"id":0,"name":"test user 0"}';
    const count = Math.ceil(targetBytes / (singleItem.length + 1));

    for (let i = 0; i < count; i++) {
      items.push(`{"id":${i},"name":"test user ${i}"}`);
    }
    const payload = `[${items.join(",")}]`;

    const result = validate(payload, schema);
    expect(result.valid).toBe(true);
    expect(result.durationMs).toBeLessThan(200);
  });
});
